{
  "lesson_summary": "Today's lesson plans to teach students to count numbers from 0 to 9, write numbers up to 9 in numerals and in words, and read numbers up to 9 in numerals and in words. The lesson uses examples like counting two raised fingers and writing the numeral and word for it, and practicing writing the number 6 in words and the number word 'four' in numerals.",
  "lesson_summary_short": "Today's lesson plans to teach counting numbers from 0 to 9, using two raised fingers as an example.",
  "checks_summary": "This quiz checks whether the class can count objects, write numerals, and match number words to numerals for numbers up to 9.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "Which shows 'two' fingers?",
      "options": [
        "Two fingers",
        "Three fingers",
        "One finger"
      ],
      "correct_index": 0,
      "explanation": "Counting 'one, two' shows two fingers.",
      "selected_because": "The lesson started with counting two raised fingers.",
      "distractor_misconceptions": {
        "1": "Confuses 'two' with 'three'",
        "2": "Confuses 'two' with 'one'"
      },
      "option_feedback": {
        "correct": "Yes, two raised fingers represent the number 'two'.",
        "wrong": {
          "1": "This shows three fingers. When you count 'one, two', you are showing two fingers.",
          "2": "This shows one finger. When you count 'one, two', you are showing two fingers."
        }
      },
      "figure": {
        "type": "count_objects",
        "rows": [
          {
            "picto": "finger",
            "count": 2,
            "label": "Two fingers"
          },
          {
            "picto": "finger",
            "count": 3,
            "label": "Three fingers"
          },
          {
            "picto": "finger",
            "count": 1,
            "label": "One finger"
          }
        ]
      },
      "figure_role": "read_off",
      "source_quote": "Two raised fingers: one, two. Write 2, two.",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "How many butterflies are there?",
      "options": [
        "4",
        "6",
        "5"
      ],
      "correct_index": 1,
      "explanation": "Counting the butterflies one by one gives a total of 6.",
      "selected_because": "The class practiced counting butterflies and writing the numeral.",
      "distractor_misconceptions": {
        "0": "Miscounts the number of butterflies",
        "2": "Confuses the count with another number"
      },
      "option_feedback": {
        "correct": "That's right! There are 6 butterflies in the picture.",
        "wrong": {
          "0": "Count the butterflies carefully, touching each one as you count. You will find there are 6 butterflies.",
          "2": "Let's count them together: one, two, three, four, five, six. There are 6 butterflies."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "butterfly",
        "count": 6
      },
      "figure_role": "count_compare",
      "source_quote": "Count the butterflies and write the numeral in the box.",
      "teaching_error": null
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which word is for the numeral 6?",
      "options": [
        "six",
        "five",
        "four"
      ],
      "correct_index": 0,
      "explanation": "The numeral 6 is written as the word 'six'.",
      "selected_because": "The class practiced writing the number 6 in words.",
      "distractor_misconceptions": {
        "1": "Confuses 'six' with 'five' due to similar sounds",
        "2": "Confuses 'six' with 'four'"
      },
      "option_feedback": {
        "correct": "Correct! The word for the numeral 6 is 'six'.",
        "wrong": {
          "1": "The word 'five' is for the numeral 5. The numeral 6 is written as 'six'.",
          "2": "The word 'four' is for the numeral 4. The numeral 6 is written as 'six'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Write the number 6 in words.",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which numeral is for 'four'?",
      "options": [
        "5",
        "4",
        "6"
      ],
      "correct_index": 1,
      "explanation": "The number word 'four' is written as the numeral 4.",
      "selected_because": "The class practiced writing the number word 'four' in numerals.",
      "distractor_misconceptions": {
        "0": "Confuses 'four' with 'five'",
        "2": "Confuses 'four' with 'six'"
      },
      "option_feedback": {
        "correct": "That's right! The numeral for 'four' is 4.",
        "wrong": {
          "0": "The numeral 5 is for the word 'five'. The number word 'four' is written as 4.",
          "2": "The numeral 6 is for the word 'six'. The number word 'four' is written as 4."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Write the number word four in numerals.",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many flowers are there?",
      "options": [
        "7",
        "5",
        "6"
      ],
      "correct_index": 0,
      "explanation": "Counting the flowers one by one gives a total of 7.",
      "selected_because": "The lesson involved counting groups of objects.",
      "distractor_misconceptions": {
        "1": "Miscounts the number of flowers",
        "2": "Confuses the count with another number"
      },
      "option_feedback": {
        "correct": "Excellent! There are 7 flowers in the picture.",
        "wrong": {
          "1": "Count each flower carefully. You will find there are 7 flowers.",
          "2": "Let's count them: one, two, three, four, five, six, seven. There are 7 flowers."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "flower",
        "count": 7
      },
      "figure_role": "count_compare",
      "source_quote": "students will count numbers from 0 to 9",
      "teaching_error": null
    },
    {
      "slo_id": "S4",
      "level": "understand",
      "question": "What number is shown?",
      "options": [
        "3",
        "2",
        "4"
      ],
      "correct_index": 0,
      "explanation": "The picture shows three counters, so the number is 3.",
      "selected_because": "The lesson focused on reading numbers from groups of objects.",
      "distractor_misconceptions": {
        "1": "Miscounts the number of counters",
        "2": "Confuses the count with another number"
      },
      "option_feedback": {
        "correct": "You got it! The picture shows the number 3.",
        "wrong": {
          "1": "Count the counters one by one. There are 3 counters.",
          "2": "Let's count them together: one, two, three. The number shown is 3."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 3
      },
      "figure_role": "read_off",
      "source_quote": "read numbers up to 9 in numerals",
      "teaching_error": null
    },
    {
      "slo_id": "S5",
      "level": "understand",
      "question": "Which word is 'one'?",
      "options": [
        "one",
        "two",
        "zero"
      ],
      "correct_index": 0,
      "explanation": "The word 'one' is the correct spelling for the number 1.",
      "selected_because": "The lesson covered reading numbers up to 9 in words.",
      "distractor_misconceptions": {
        "1": "Confuses 'one' with 'two'",
        "2": "Confuses 'one' with 'zero'"
      },
      "option_feedback": {
        "correct": "Yes, 'one' is the word for the number 1.",
        "wrong": {
          "1": "This word is 'two'. The word for the number 1 is 'one'.",
          "2": "This word is 'zero'. The word for the number 1 is 'one'."
        }
      },
      "figure": {
        "type": "word_blank",
        "word": "one",
        "blanks": []
      },
      "figure_role": null,
      "source_quote": "read numbers up to 9 in words",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "apply",
      "question": "What happens when you count objects?",
      "options": [
        "The last word counted is the total.",
        "You count each object twice.",
        "You skip some objects."
      ],
      "correct_index": 0,
      "explanation": "When counting, the last number you say tells you the total number of objects.",
      "selected_because": "The lesson emphasized that the last count word is what you write.",
      "distractor_misconceptions": {
        "1": "Misunderstands the process of counting",
        "2": "Believes skipping objects is part of counting"
      },
      "option_feedback": {
        "correct": "That's right! The last word you say when counting is the total number of objects.",
        "wrong": {
          "1": "Counting each object twice will give you the wrong total. You should touch each object only once as you count.",
          "2": "Skipping objects means you won't get the correct total. You need to count every object."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Count with one touch per object; the last count word is what you write.",
      "teaching_error": null
    }
  ]
}
